import React, { useId } from 'react';
import { cn } from './cn';

/** Shared control surface: one height, radius, border and focus treatment. */
export const CONTROL_BASE =
  'w-full rounded-control bg-surface-2 border text-zinc-100 placeholder:text-zinc-500 ' +
  'transition-colors focus:outline-none focus:border-accent disabled:opacity-50 disabled:cursor-not-allowed';
const CONTROL_OK = 'border-line-strong';
const CONTROL_ERR = 'border-danger focus:border-danger';

interface FieldProps {
  label?: string;
  hint?: string;
  error?: string;
  /** id of the control being labelled (generated by Input/Select/Textarea). */
  htmlFor: string;
  className?: string;
  children: React.ReactNode;
}

/** Label + control + hint/error. Error text replaces the hint and is announced. */
export const Field: React.FC<FieldProps> = ({ label, hint, error, htmlFor, className, children }) => (
  <div className={cn('flex flex-col gap-1.5 min-w-0', className)}>
    {label && (
      <label htmlFor={htmlFor} className="text-xs font-medium text-zinc-300">
        {label}
      </label>
    )}
    {children}
    {error ? (
      <p id={`${htmlFor}-msg`} role="alert" className="text-label text-danger">
        {error}
      </p>
    ) : hint ? (
      <p id={`${htmlFor}-msg`} className="text-label text-zinc-500">
        {hint}
      </p>
    ) : null}
  </div>
);

interface SharedProps {
  label?: string;
  hint?: string;
  error?: string;
  /** Monospace tabular text, for numeric entry (weight, reps, macros). */
  mono?: boolean;
  wrapperClassName?: string;
}

type InputProps = SharedProps & Omit<React.InputHTMLAttributes<HTMLInputElement>, 'className'> & { className?: string };

export const Input: React.FC<InputProps> = ({ label, hint, error, mono, wrapperClassName, className, id, ...rest }) => {
  const auto = useId();
  const cid = id ?? auto;
  return (
    <Field label={label} hint={hint} error={error} htmlFor={cid} className={wrapperClassName}>
      <input
        id={cid}
        aria-invalid={error ? true : undefined}
        aria-describedby={error || hint ? `${cid}-msg` : undefined}
        className={cn(CONTROL_BASE, error ? CONTROL_ERR : CONTROL_OK, 'h-11 px-3 text-sm', mono && 'font-mono font-semibold tabular', className)}
        {...rest}
      />
    </Field>
  );
};

type SelectProps = SharedProps & Omit<React.SelectHTMLAttributes<HTMLSelectElement>, 'className'> & { className?: string };

export const Select: React.FC<SelectProps> = ({ label, hint, error, mono, wrapperClassName, className, id, children, ...rest }) => {
  const auto = useId();
  const cid = id ?? auto;
  return (
    <Field label={label} hint={hint} error={error} htmlFor={cid} className={wrapperClassName}>
      <select
        id={cid}
        aria-invalid={error ? true : undefined}
        aria-describedby={error || hint ? `${cid}-msg` : undefined}
        className={cn(CONTROL_BASE, error ? CONTROL_ERR : CONTROL_OK, 'h-11 px-3 text-sm', mono && 'font-mono font-semibold', className)}
        {...rest}
      >
        {children}
      </select>
    </Field>
  );
};

type TextareaProps = SharedProps & Omit<React.TextareaHTMLAttributes<HTMLTextAreaElement>, 'className'> & { className?: string };

export const Textarea: React.FC<TextareaProps> = ({ label, hint, error, mono, wrapperClassName, className, id, rows = 3, ...rest }) => {
  const auto = useId();
  const cid = id ?? auto;
  return (
    <Field label={label} hint={hint} error={error} htmlFor={cid} className={wrapperClassName}>
      <textarea
        id={cid}
        rows={rows}
        aria-invalid={error ? true : undefined}
        aria-describedby={error || hint ? `${cid}-msg` : undefined}
        className={cn(CONTROL_BASE, error ? CONTROL_ERR : CONTROL_OK, 'px-3 py-2.5 text-sm resize-y', mono && 'font-mono', className)}
        {...rest}
      />
    </Field>
  );
};
